export const n = 27;
export const num = "27";
export const title = "Rulesets — سیاست شاخه در سطح سازمان";
export const label = "فصل ۲۷ · Rulesets";
export const part = 2;
export const html = "<p class=\"lead\">Ruleset مجموعهٔ قوانین روی شاخه است — مثلاً push مستقیم به <code>main</code> ممنوع، CI باید سبز باشد، Merge فقط بعد از Approve. از Branch Protection قدیمی کامل‌تر است.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>Ruleset را به‌جای یک تیک ساده طراحی کنی</li>\n<li>required checks، review و linear history را قفل کنی</li>\n<li>Environments را برای production بفهمی</li>\n<li>CODEOWNERS را به سیاست وصل کنی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">🧱 چرا Rulesets؟</span></span></h2>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th></th>\n<th>Branch protection</th>\n<th>Rulesets</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>تعداد سیاست</td>\n<td>یکی per branch</td>\n<td>چند لایه قابل‌ترکیب</td>\n</tr>\n<tr>\n<td>هدف</td>\n<td>نام شاخه</td>\n<td>الگو (<code>release/**</code>) + tagging</td>\n</tr>\n<tr>\n<td>Bypass</td>\n<td>ضعیف</td>\n<td>نقش / تیم / App مشخص</td>\n</tr>\n<tr>\n<td>سازمان</td>\n<td>محدود</td>\n<td>ارث‌بری Enterprise → Org → Repo</td>\n</tr>\n<tr>\n<td>ارزیابی</td>\n<td>—</td>\n<td>تاریخچهٔ ارزیابی و بینش</td>\n</tr>\n</tbody>\n</table></div><p class=\"keep-next\">حداقل سیاست <code>main</code> در ۲۰۲۶:</p>\n<ol>\n<li>Restrict deletions</li>\n<li>Block force pushes</li>\n<li>Require a pull request (۱–۲ Approve)</li>\n<li>Require status checks to pass (CI)</li>\n<li>Require conversation resolution</li>\n<li>Require signed commits (اگر تیم آماده است)</li>\n<li>Dismiss stale reviews on new push</li>\n<li>Require review from Code Owners</li>\n</ol>\n<h2><span class=\"hx\"><span class=\"hx-t\">👥 CODEOWNERS</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">.github/CODEOWNERS</span></div><pre>*                    @rezaian-dev\n/src/build.py        @rezaian-dev\n/docs/               @docs-team\n*.yml                @platform-team\n</pre></div>\n<p>آخرین قانونِ مطابق برنده است. بدون Ruleset «code owners»، این فایل فقط مستندات است.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🌍 Environments</span></span></h2>\n<p class=\"keep-next\">برای Actions:</p>\n<ul>\n<li><code>staging</code> — بدون دروازه</li>\n<li><code>production</code> — required reviewers + wait timer + restricted secrets</li>\n</ul>\n<p>حتی اگر شاخه آزاد باشد، deploy به production بدون Approve انسانی نمی‌رود. از ۲۰۲۵ <strong>Immutable Releases</strong> هم دارایی و تگ عرضه را قفل می‌کند.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🖥️ اثر روی VS Code</span></span></h2>\n<p class=\"keep-next\">اگر مستقیم روی <code>main</code> کامیت کنی:</p>\n<ul>\n<li>محلی: <code>git.branchProtection</code> هشدار می‌دهد</li>\n<li>push: سرور رد می‌کند با پیام Ruleset</li>\n</ul>\n<p>پیام خطا را بخوان؛ معمولاً لینک به کدام rule است.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">Repository ruleset برای تگ</div>\n<p><code>v*</code> را قفل کن تا کسی تگ نسخه را جابه‌جا نکند. همراه Immutable Releases، عرضه قابل‌اثبات می‌شود.</p>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Mid — linear history یعنی چه؟</strong> فقط fast-forward؛ merge commit روی main ممنوع. با squash یا rebase merge جور است.</p>\n<p><strong>Senior — bypass چه کسی باید داشته باشد؟</strong> فقط bot حادثه و چند admin. اگر همه bypass دارند، سیاست تئاتر است.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>force push روی main بسته است</li>\n<li>CI required است نه تزئینی</li>\n<li>production Environment Approve دارد</li>\n<li>CODEOWNERS زنده است</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> GitHub Actions از صفر تا OIDC.</p></div>";
export default { n, num, title, label, part, html };
